//! Response body: generated content streamed in chunks, optionally throttled or aborted.

use crate::content;
use bytes::Bytes;
use futures_util::{Stream, StreamExt, stream};
use hyper::body::{Body, Frame, SizeHint};
use std::io;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::time::Duration;

const CHUNK: u64 = 64 * 1024;
const SLOW_TICK: Duration = Duration::from_millis(100);
/// Time given to hyper to flush the headers and prefix before a `drop_after` abort. The abort
/// is timing-dependent by nature: without this grace hyper discards unflushed headers when the
/// body errors immediately, so the client would see a reset with no status line.
const FLUSH_GRACE: Duration = Duration::from_millis(150);
const TICKS_PER_SECOND: u64 = 10;

type ChunkStream = Pin<Box<dyn Stream<Item = Result<Bytes, io::Error>> + Send>>;

/// How a generated body is delivered.
#[derive(Debug, Clone, Copy, Default)]
pub struct Delivery {
    /// Throttle to about this many bytes per second.
    pub slow_bps: Option<u64>,
    /// Abort the connection once this many body bytes were sent.
    pub drop_after: Option<u64>,
}

/// The body type for every fixture response.
pub struct FixtureBody {
    stream: ChunkStream,
    exact_len: Option<u64>,
}

impl FixtureBody {
    /// An empty body that still reports an exact length of zero.
    #[must_use]
    pub fn empty() -> Self {
        Self {
            stream: Box::pin(stream::empty()),
            exact_len: Some(0),
        }
    }

    /// A small fixed body.
    #[must_use]
    pub fn from_bytes(data: Bytes) -> Self {
        let len = u64::try_from(data.len()).unwrap_or(u64::MAX);
        Self {
            stream: Box::pin(stream::once(async move { Ok(data) })),
            exact_len: Some(len),
        }
    }

    /// Generated bytes `[start, start + len)` of the `seed` stream.
    ///
    /// With `exact_length` the body advertises its size (Content-Length); without it the length
    /// is unknown and hyper falls back to chunked transfer encoding.
    #[must_use]
    pub fn generated(
        seed: u64,
        start: u64,
        len: u64,
        exact_length: bool,
        delivery: Delivery,
    ) -> Self {
        let state = GenState::new(seed, start, len, delivery);
        let stream = stream::unfold(state, GenState::next_chunk);
        Self {
            stream: Box::pin(stream),
            exact_len: exact_length.then_some(len),
        }
    }
}

impl Body for FixtureBody {
    type Data = Bytes;
    type Error = io::Error;

    fn poll_frame(
        mut self: Pin<&mut Self>,
        cx: &mut Context<'_>,
    ) -> Poll<Option<Result<Frame<Bytes>, io::Error>>> {
        self.stream
            .poll_next_unpin(cx)
            .map(|item| item.map(|r| r.map(Frame::data)))
    }

    fn size_hint(&self) -> SizeHint {
        self.exact_len
            .map_or_else(SizeHint::default, SizeHint::with_exact)
    }
}

struct GenState {
    seed: u64,
    pos: u64,
    end: u64,
    cutoff: u64,
    chunk: u64,
    delay: Option<Duration>,
    sent_any: bool,
    failed: bool,
}

impl GenState {
    fn new(seed: u64, start: u64, len: u64, delivery: Delivery) -> Self {
        let end = start.saturating_add(len);
        let chunk = delivery
            .slow_bps
            .map_or(CHUNK, |bps| (bps / TICKS_PER_SECOND).clamp(1, CHUNK));
        Self {
            seed,
            pos: start,
            end,
            cutoff: delivery
                .drop_after
                .map_or(u64::MAX, |n| start.saturating_add(n)),
            chunk,
            delay: delivery.slow_bps.map(|_| SLOW_TICK),
            sent_any: false,
            failed: false,
        }
    }

    async fn next_chunk(mut self) -> Option<(Result<Bytes, io::Error>, Self)> {
        if self.failed || self.pos >= self.end {
            return None;
        }
        if self.pos >= self.cutoff {
            self.failed = true;
            // Yield to the connection task (Pending) so hyper flushes the bytes already queued
            // before the abort; otherwise the headers and prefix could be discarded unsent.
            tokio::time::sleep(FLUSH_GRACE).await;
            let err = io::Error::new(
                io::ErrorKind::ConnectionAborted,
                "fixture drop_after reached",
            );
            return Some((Err(err), self));
        }
        if let (Some(delay), true) = (self.delay, self.sent_any) {
            tokio::time::sleep(delay).await;
        }
        let n = self.chunk.min(self.end.min(self.cutoff) - self.pos);
        let mut buf = vec![0u8; usize::try_from(n).unwrap_or(0)];
        content::fill(self.seed, self.pos, &mut buf);
        self.pos += n;
        self.sent_any = true;
        Some((Ok(Bytes::from(buf)), self))
    }
}
